-- supabase/migrations/001_create_profiles.sql
--
-- One profile per Supabase Auth user. `id` is the Auth UUID; `user_id` is
-- the human-readable company ID used to sign in (ADM0001, HR0001,
-- EMP0001, INT0001), generated by public.generate_user_code().

CREATE TABLE IF NOT EXISTS public.profiles (
    id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
    user_id TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE,
    role TEXT NOT NULL CHECK (
        role IN ('Admin', 'HR', 'Employee', 'Intern')
    ),
    department TEXT,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    -- TRUE while the person is on a Draft, Published, or In Progress
    -- project. Maintained by triggers (see 009).
    assigned BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;

CREATE INDEX IF NOT EXISTS idx_profiles_role
    ON public.profiles(role);

CREATE INDEX IF NOT EXISTS idx_profiles_active
    ON public.profiles(is_active);

CREATE OR REPLACE FUNCTION public.set_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS profiles_set_updated_at
    ON public.profiles;

CREATE TRIGGER profiles_set_updated_at
BEFORE UPDATE ON public.profiles
FOR EACH ROW
EXECUTE FUNCTION public.set_updated_at();
